// Verify leaderboard data exists before astro build.
//
// These files are committed to git and regenerated by export_game.py and
// `make leaderboard`.  This script just asserts they're present — if they're
// missing, the repo checkout is broken.
const fs = require("fs");

const REQUIRED = [
  "src/data/benchmark-results.json",
  "src/data/model-stats.json",
];

for (const path of REQUIRED) {
  if (!fs.existsSync(path)) {
    console.error(`Missing ${path} — run 'make leaderboard' to regenerate`);
    process.exit(1);
  }
}
